<?php $tituloPaginaAdmin='Gestão de produtos';require __DIR__.'/../includes/cabecalho-admin.php';$db=criarConexaoBancoDados();if($_SERVER['REQUEST_METHOD']==='POST'){if(isset($_POST['excluir'])){$db->prepare('DELETE FROM produtos WHERE id=?')->execute([(int)$_POST['id']]);}else{$v=[trim($_POST['nome']),trim($_POST['descricao']),(float)$_POST['preco'],(int)$_POST['artista_id'],trim($_POST['categoria']),(int)$_POST['estoque'],trim($_POST['imagem']),trim($_POST['cor']),trim($_POST['tamanho']),(int)isset($_POST['destaque'])];if((int)$_POST['id']){$v[]=(int)$_POST['id'];$db->prepare('UPDATE produtos SET nome=?,descricao=?,preco=?,artista_id=?,categoria=?,estoque=?,imagem=?,cor=?,tamanho=?,destaque=? WHERE id=?')->execute($v);}else{$db->prepare('INSERT INTO produtos(nome,descricao,preco,artista_id,categoria,estoque,imagem,cor,tamanho,destaque) VALUES(?,?,?,?,?,?,?,?,?,?)')->execute($v);}}redirecionar('produtos.php');}$ed=null;if(isset($_GET['editar'])){$s=$db->prepare('SELECT * FROM produtos WHERE id=?');$s->execute([(int)$_GET['editar']]);$ed=$s->fetch();}$arts=$db->query('SELECT * FROM artistas ORDER BY nome')->fetchAll();$prods=$db->query('SELECT p.*,a.nome artista FROM produtos p JOIN artistas a ON a.id=p.artista_id ORDER BY p.id DESC')->fetchAll();?><h1>Produtos</h1><form method="post" class="form-admin"><input type="hidden" name="id" value="<?=$ed['id']??0?>"><input required name="nome" placeholder="Nome" value="<?=escapar($ed['nome']??'')?>"><textarea required name="descricao" placeholder="Descrição"><?=escapar($ed['descricao']??'')?></textarea><input required step="0.01" type="number" name="preco" placeholder="Preço" value="<?=$ed['preco']??''?>"><select name="artista_id"><?php foreach($arts as $a):?><option value="<?=$a['id']?>" <?=($ed['artista_id']??0)==$a['id']?'selected':''?>><?=escapar($a['nome'])?></option><?php endforeach;?></select><input required name="categoria" placeholder="Categoria" value="<?=escapar($ed['categoria']??'')?>"><input required type="number" name="estoque" placeholder="Estoque" value="<?=$ed['estoque']??0?>"><input name="imagem" placeholder="URL/caminho da imagem" value="<?=escapar($ed['imagem']??'')?>"><input name="cor" placeholder="Cor" value="<?=escapar($ed['cor']??'')?>"><input name="tamanho" placeholder="Tamanho" value="<?=escapar($ed['tamanho']??'')?>"><label><input type="checkbox" name="destaque" <?=!empty($ed['destaque'])?'checked':''?>> Destaque</label><button>Salvar produto</button></form><table><tr><th>Produto</th><th>Artista</th><th>Preço</th><th></th></tr><?php foreach($prods as $p):?><tr><td><?=escapar($p['nome'])?></td><td><?=escapar($p['artista'])?></td><td><?=valorMoeda((float)$p['preco'])?></td><td><a href="?editar=<?=$p['id']?>">Editar</a> <form method="post"><input type="hidden" name="id" value="<?=$p['id']?>"><button name="excluir">Excluir</button></form></td></tr><?php endforeach;?></table><?php require __DIR__.'/../includes/rodape-admin.php';?>